package local.skyfamily;
import android.content.SharedPreferences;import android.os.*;import org.json.*;
final class ForecastRefresh {
 static final long INTERVAL=900000L;final CalendarPhotosActivity host;final Handler main=new Handler();boolean running=false,closed=false,inFlight=false,startupPending=true;long retryAfter=0,seenForeground=-1;String retryPlace="";final Runnable tick=this::check;final Runnable notifyViews=this::updateViews;final SharedPreferences.OnSharedPreferenceChangeListener changes=this::changed;
 ForecastRefresh(CalendarPhotosActivity activity){host=activity;}
 JSONObject json(String key){try{return new JSONObject(host.get(key));}catch(Exception error){return null;}}
 String place(JSONObject location){return location==null?"":location.optString("latitude")+","+location.optString("longitude");}
 void start(){if(closed)return;long foreground=LegacyDashApp.foregroundEpoch;if(seenForeground!=foreground){seenForeground=foreground;startupPending=true;retryAfter=0;}if(!running){running=true;host.prefs.registerOnSharedPreferenceChangeListener(changes);}main.removeCallbacks(tick);main.post(tick);queueViews();}
 void stop(){if(running)host.prefs.unregisterOnSharedPreferenceChangeListener(changes);running=false;main.removeCallbacks(tick);main.removeCallbacks(notifyViews);}
 void close(){stop();closed=true;}
 void changed(SharedPreferences preferences,String key){if(!running||closed)return;if("planetary.location".equals(key)){retryAfter=0;retryPlace="";main.removeCallbacks(tick);main.post(tick);queueViews();}else if("planetary.cache".equals(key)){main.removeCallbacks(tick);main.post(tick);queueViews();}}
 void queueViews(){if(!running||closed)return;main.removeCallbacks(notifyViews);main.post(notifyViews);}
 void updateViews(){if(running&&!closed)host.forecastCacheChanged();}
 void schedule(long delay){main.removeCallbacks(tick);if(running&&!closed)main.postDelayed(tick,Math.max(1000L,delay));}
 boolean fresh(JSONObject cache,String selected,long now){if(cache==null||!selected.equals(cache.optString("place"))||cache.optJSONObject("data")==null)return false;long age=now-cache.optLong("fetched");return age>=0&&age<INTERVAL;}
 void check(){if(!running||closed)return;JSONObject location=json("planetary.location");if(location==null)return;String selected=place(location);long now=System.currentTimeMillis();JSONObject cache=json("planetary.cache");if(!startupPending&&fresh(cache,selected,now)){schedule(INTERVAL-(now-cache.optLong("fetched")));return;}if(inFlight){schedule(1000);return;}long remaining=retryAfter-SystemClock.elapsedRealtime();if(!startupPending&&selected.equals(retryPlace)&&remaining>0){schedule(remaining);return;}startupPending=false;queueViews();inFlight=true;retryPlace=selected;retryAfter=SystemClock.elapsedRealtime()+INTERVAL;final long started=now;host.work(()->{try{double latitude=location.getDouble("latitude"),longitude=location.getDouble("longitude");if(Double.isNaN(latitude)||Double.isInfinite(latitude)||Double.isNaN(longitude)||Double.isInfinite(longitude)||Math.abs(latitude)>90||Math.abs(longitude)>180)throw new IllegalArgumentException("Invalid weather location");String url="https://api.open-meteo.com/v1/forecast?latitude="+latitude+"&longitude="+longitude+"&current=temperature_2m,relative_humidity_2m,apparent_temperature,is_day,precipitation,weather_code,cloud_cover,pressure_msl,wind_speed_10m,wind_direction_10m,wind_gusts_10m&hourly=temperature_2m,precipitation_probability,wind_speed_10m&daily=weather_code,temperature_2m_max,temperature_2m_min,sunrise,sunset,precipitation_sum,precipitation_probability_max,wind_speed_10m_max,uv_index_max&temperature_unit=fahrenheit&wind_speed_unit=mph&precipitation_unit=inch&timezone=auto&forecast_days=7";JSONObject data=new JSONObject(new String(host.request(url,"GET",null,"",2000000),"UTF-8"));data.getJSONObject("current");long fetched=System.currentTimeMillis();JSONObject record=new JSONObject().put("place",selected).put("fetched",fetched).put("data",data);main.post(()->{inFlight=false;if(closed)return;if(selected.equals(place(json("planetary.location")))){JSONObject newer=json("planetary.cache");if(newer==null||!selected.equals(newer.optString("place"))||newer.optLong("fetched")<started)host.save("planetary.cache",record.toString());}if(running){queueViews();main.removeCallbacks(tick);main.post(tick);}});}catch(Exception error){main.post(()->{inFlight=false;if(closed)return;if(running){queueViews();if(!selected.equals(place(json("planetary.location")))){main.removeCallbacks(tick);main.post(tick);}else schedule(Math.max(1000L,retryAfter-SystemClock.elapsedRealtime()));}});}});}
}
